package forth

import (
	"errors"
	"strconv"
	"strings"
)

// Forth evaluates a small subset of the Forth language. Each element of input
// is a line of source; the result is the final contents of the data stack.
func Forth(input []string) ([]int, error) {
	stack := []int{}
	words := map[string][]string{}

	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); i++ {
			if tokens[i] == ":" {
				i++
				if i >= len(tokens) {
					return nil, errors.New("incomplete definition")
				}
				name := strings.ToLower(tokens[i])
				if isNumber(name) {
					return nil, errors.New("cannot redefine a number")
				}
				i++
				body := []string{}
				for i < len(tokens) && tokens[i] != ";" {
					body = append(body, tokens[i])
					i++
				}
				if i >= len(tokens) {
					return nil, errors.New("incomplete definition")
				}
				words[name] = inline(body, words)
				i++ // skip the terminating ';'
				continue
			}
			if err := execToken(tokens[i], &stack, words); err != nil {
				return nil, err
			}
		}
	}
	return stack, nil
}

// inline expands user-defined words in a definition body into their current
// definitions, so a word captures the meaning of the words it uses at the
// time it is defined. Built-in words and numbers are left as-is.
func inline(body []string, words map[string][]string) []string {
	out := []string{}
	for _, tok := range body {
		if def, ok := words[strings.ToLower(tok)]; ok {
			out = append(out, def...)
		} else {
			out = append(out, tok)
		}
	}
	return out
}

// execToken executes a single token: a number is pushed, a user-defined word
// runs its (already inlined) body, and anything else is a built-in.
func execToken(tok string, stack *[]int, words map[string][]string) error {
	if isNumber(tok) {
		n, _ := strconv.Atoi(tok)
		*stack = append(*stack, n)
		return nil
	}
	name := strings.ToLower(tok)
	if def, ok := words[name]; ok {
		for _, bt := range def {
			if err := execToken(bt, stack, words); err != nil {
				return err
			}
		}
		return nil
	}
	return execBuiltin(name, stack)
}

func execBuiltin(name string, stack *[]int) error {
	switch name {
	case "+", "-", "*", "/":
		if len(*stack) < 2 {
			return errors.New("stack underflow")
		}
		b := (*stack)[len(*stack)-1]
		a := (*stack)[len(*stack)-2]
		*stack = (*stack)[:len(*stack)-2]
		switch name {
		case "+":
			*stack = append(*stack, a+b)
		case "-":
			*stack = append(*stack, a-b)
		case "*":
			*stack = append(*stack, a*b)
		case "/":
			if b == 0 {
				return errors.New("divide by zero")
			}
			*stack = append(*stack, a/b)
		}
		return nil
	case "dup":
		if len(*stack) < 1 {
			return errors.New("stack underflow")
		}
		*stack = append(*stack, (*stack)[len(*stack)-1])
		return nil
	case "drop":
		if len(*stack) < 1 {
			return errors.New("stack underflow")
		}
		*stack = (*stack)[:len(*stack)-1]
		return nil
	case "swap":
		if len(*stack) < 2 {
			return errors.New("stack underflow")
		}
		n := len(*stack)
		(*stack)[n-1], (*stack)[n-2] = (*stack)[n-2], (*stack)[n-1]
		return nil
	case "over":
		if len(*stack) < 2 {
			return errors.New("stack underflow")
		}
		*stack = append(*stack, (*stack)[len(*stack)-2])
		return nil
	default:
		return errors.New("undefined operation")
	}
}

// isNumber reports whether s is an integer literal (an optional leading '-'
// followed by one or more ASCII digits).
func isNumber(s string) bool {
	start := 0
	if s[0] == '-' {
		start = 1
	}
	if start >= len(s) {
		return false
	}
	for i := start; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

